  let state=defaults(),view='search',equipmentTab='weapons',databaseTab='armor',dbQuery='',dbPart='',dbPage=1,results=[],selected=0,searchStatus='idle',searchStats={},elapsed=0,worker=null,workerUrl=null,fallbackIterator=null,runId=0,sort='potential',toastTimer,expandedResult=null,improvementPrevious=null,damageEditingWeapon=null;
