    for(const id of ['#close-damage-dialog','#done-damage-dialog'])$(id).onclick=()=>$('#damage-dialog').close();
    if($('#damage-profile-type'))$('#damage-profile-type').onchange=e=>{state.damageSelections[weapon.id]={...state.damageSelections[weapon.id],type:e.target.value};save();refreshMeta();refreshDamage();renderResults();renderDamageDialog();};
